type Settings = { voice: VoiceChoice; nickname: string; minTurnMs: number; muteInMeetings: boolean; phrases: Phrases }

function readOptions(options: PluginOptions): Settings {
  const language: Language = Object.hasOwn(PHRASES, String(options.language)) ? (options.language as Language) : 'en'
  const voice: VoiceChoice = ['female', 'male', 'alternate'].includes(String(options.voice)) ? (options.voice as VoiceChoice) : 'random'
  const nickname = typeof options.nickname === 'string' ? options.nickname.trim() : ''
  const minSeconds = Number(options.minSeconds)
  const minTurnMs = Number.isFinite(minSeconds) && minSeconds > 0 ? minSeconds * 1000 : 0
  const muteInMeetings = options.muteInMeetings !== 'off'
  return { voice, nickname, minTurnMs, muteInMeetings, phrases: PHRASES[language] }
}

function toolLabel({ phrases }: Settings, tool: string): string {
  if (phrases.tools[tool]) return phrases.tools[tool]
  const name = tool.startsWith('mcp__') ? (tool.split('__').at(-1) ?? tool).replaceAll('_', ' ') : tool
  return phrases.otherTool(name)
}

function withName({ nickname, phrases }: Settings, text: string): string {
  return nickname ? `${nickname}${phrases.separator}${text}` : text
}

// Prints `busy` while any app records from a microphone or a camera, `free` otherwise.
const IN_USE_SWIFT = `import AVFoundation
import CoreAudio

func micInUse() -> Bool {
  var addr = AudioObjectPropertyAddress(mSelector: kAudioHardwarePropertyDevices, mScope: kAudioObjectPropertyScopeGlobal, mElement: kAudioObjectPropertyElementMain)
  var size: UInt32 = 0
  AudioObjectGetPropertyDataSize(AudioObjectID(kAudioObjectSystemObject), &addr, 0, nil, &size)
  var ids = [AudioDeviceID](repeating: 0, count: Int(size) / MemoryLayout<AudioDeviceID>.size)
  AudioObjectGetPropertyData(AudioObjectID(kAudioObjectSystemObject), &addr, 0, nil, &size, &ids)
  return ids.contains { id in
    var input = AudioObjectPropertyAddress(mSelector: kAudioDevicePropertyStreamConfiguration, mScope: kAudioObjectPropertyScopeInput, mElement: kAudioObjectPropertyElementMain)
    var s: UInt32 = 0
    guard AudioObjectGetPropertyDataSize(id, &input, 0, nil, &s) == noErr, s > 0 else { return false }
    let buf = UnsafeMutableRawPointer.allocate(byteCount: Int(s), alignment: 16)
    defer { buf.deallocate() }
    guard AudioObjectGetPropertyData(id, &input, 0, nil, &s, buf) == noErr,
          UnsafeMutableAudioBufferListPointer(buf.assumingMemoryBound(to: AudioBufferList.self)).count > 0 else { return false }
    var running = AudioObjectPropertyAddress(mSelector: kAudioDevicePropertyDeviceIsRunningSomewhere, mScope: kAudioObjectPropertyScopeGlobal, mElement: kAudioObjectPropertyElementMain)
    var value: UInt32 = 0
    var valueSize = UInt32(MemoryLayout<UInt32>.size)
    return AudioObjectGetPropertyData(id, &running, 0, nil, &valueSize, &value) == noErr && value != 0
  }
}

func cameraInUse() -> Bool {
  AVCaptureDevice.DiscoverySession(deviceTypes: [.builtInWideAngleCamera, .external, .continuityCamera], mediaType: .video, position: .unspecified)
    .devices.contains { $0.isInUseByAnotherApplication }
}

print(micInUse() || cameraInUse() ? "busy" : "free")
`

const IN_USE_BINARY = 'in-use-v1'

let inUseBinary: Promise<string | undefined> | undefined

async function buildInUseBinary($: EngineInterface, home: string): Promise<string | undefined> {
  const dir = `${home}/.cache/call-my-name`
  const binary = `${dir}/${IN_USE_BINARY}`
  if (await $.fs.exists(binary)) return binary
  await $.fs.write(`${dir}/${IN_USE_BINARY}.swift`, IN_USE_SWIFT)
  const built = await $.process.run(['swiftc', '-O', `${dir}/${IN_USE_BINARY}.swift`, '-o', binary], { timeoutMs: 180_000 })
  return built.exitCode === 0 ? binary : undefined
}

async function isInMeeting($: EngineInterface, { muteInMeetings }: Settings): Promise<boolean> {
  if (!muteInMeetings) return false
  const home = await $.env.get('HOME')
  if (!home) return false
  inUseBinary ??= buildInUseBinary($, home).catch(() => undefined)
  const binary = await inUseBinary
  if (!binary) {
    inUseBinary = undefined
    return false
  }
  const { stdout } = await $.process.run([binary], { timeoutMs: 5_000 })
  return stdout.trim() === 'busy'
}

let spokenCount = 0

function nextEdgeVoice({ voice, phrases }: Settings): string {
  if (voice === 'female' || voice === 'male') return phrases.edgeVoices[voice]
  const useFemale = voice === 'alternate' ? spokenCount++ % 2 === 0 : Math.random() < 0.5
  return useFemale ? phrases.edgeVoices.female : phrases.edgeVoices.male
}

async function sayWithEdge($: EngineInterface, settings: Settings, text: string): Promise<boolean> {
  const edgeVoice = nextEdgeVoice(settings)
  const file = `/tmp/call-my-name-${await $.clock.now()}.mp3`
  const home = await $.env.get('HOME')
  for (const bin of home ? ['edge-tts', `${home}/.local/bin/edge-tts`] : ['edge-tts']) {
    const made = await $.process
      .run([bin, '--voice', edgeVoice, '--text', text, '--write-media', file], { timeoutMs: 10_000 })
      .catch(() => undefined)
    if (made?.exitCode !== 0) continue
    const played = await $.process.run(['afplay', file], { timeoutMs: 60_000 })
    await $.process.run(['rm', '-f', file])
    return played.exitCode === 0
  }
  return false
}

async function sayWithMacVoice($: EngineInterface, { phrases }: Settings, text: string): Promise<void> {
  const { stdout } = await $.process.run(['say', '-v', '?'])
  const installed = stdout.split('\n').map(line => line.split(/\s{2,}/)[0].trim())
  const macVoice = phrases.macVoices.find(v => installed.includes(v))
  await $.process.run(macVoice ? ['say', '-v', macVoice, text] : ['say', text], { timeoutMs: 60_000 })
}

async function say($: EngineInterface, settings: Settings, text: string): Promise<void> {
  const spoken = await sayWithEdge($, settings, text).catch(() => false)
  if (!spoken) await sayWithMacVoice($, settings, text)
}

async function sayUnlessInMeeting($: EngineInterface, settings: Settings, text: () => Promise<string>): Promise<void> {
  if (await isInMeeting($, settings).catch(() => false)) return
  await say($, settings, withName(settings, await text()))
}

function speak($: EngineInterface, settings: Settings, text: string): void {
  void sayUnlessInMeeting($, settings, async () => text).catch(() => undefined)
}

async function describeDone($: EngineInterface, { phrases }: Settings, prompt: string, answer: string): Promise<string> {
  const reply = await $.model.complete({
    model: 'haiku',
    maxTokens: 80,
    system: phrases.summarySystem,
    prompt: phrases.summaryPrompt(prompt.slice(0, 1500), answer.slice(0, 3000)),
  })
  const sentence = reply.isAnswered ? reply.text.trim().replace(/^["“”'「」]+|["“”'「」]+$/g, '') : ''
  return sentence || phrases.doneFallback
}

async function announceDone($: EngineInterface, settings: Settings, prompt: string, answer: string): Promise<void> {
  await sayUnlessInMeeting($, settings, () => describeDone($, settings, prompt, answer))
}

export const register: Register = (on, options) => {
  const settings = readOptions(options)
  const { phrases } = settings
  const prompts = new Map<string, string>()

  on('turn.start', ($, e, next) => {
    prompts.set(e.turnId, e.text)
    return next(e)
  })

  on('classic.PermissionRequest', ($, e, next) => {
    speak($, settings, phrases.permission(toolLabel(settings, e.tool_name)))
    return next(e)
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'AskUserQuestion' }, ($, e, next) => {
    speak($, settings, phrases.question(e.questions[0]?.question ?? ''))
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    const prompt = prompts.get(e.turnId) ?? ''
    prompts.delete(e.turnId)
    if (e.agentId !== undefined || e.isAborted || e.durationMs < settings.minTurnMs) return done
    if (e.reason === 'error') speak($, settings, phrases.error)
    else void announceDone($, settings, prompt, e.answer).catch(() => speak($, settings, phrases.doneFallback))
    return done
  })
}

